const e=["Dieu","Nature","Religion","Force","Lythari","Virelith"],t="Comment dominer la Nature ?",n="Déesse de la Nature",r=["Quaara représente la Nature, l’une des Forces du Monde.","Elle incarne les écosystèmes, la croissance, les cycles naturels et l’équilibre fragile entre les êtres vivants.","La Nature n’est cependant ni bonne ni mauvaise.","Elle nourrit autant qu’elle dévore.","Elle protège autant qu’elle détruit.","Une forêt peut abriter un voyageur comme elle peut l'engloutir. Une rivière peut faire vivre une cité avant de l'emporter lors d'une crue.","Quaara ne cherche pas à rendre la Nature douce.","Elle représente simplement ce qu'elle est."],s=[{label:"Domaines",value:"Nature"},{label:"Symboles",value:"Une branche, une feuille, une racine, une spirale végétale, une montagne, un arbre dont les racines entourent le monde"}],a=[{title:"La Nature",title_border:"#e8553d",type:"text",content:["Pour les mortels, la Nature est souvent opposée à la civilisation.","Pour Quaara, cette distinction n'a pas réellement de sens.","Une forêt, une montagne ou un océan sont naturels.","Mais une ville construite par des mortels l'est également.","Les êtres vivants construisent, transforment et détruisent leur environnement depuis toujours.","La véritable question n'est donc pas de savoir si les mortels doivent vivre dans la Nature.","Ils en font déjà partie.","La question est de savoir jusqu'où ils peuvent la transformer avant de rompre l'équilibre dont ils dépendent eux-mêmes."]},{title:"Le cycle",title_border:"#c2660a",type:"text",content:["Quaara est intimement liée aux cycles naturels.","La naissance entraîne la croissance.","La croissance entraîne le déclin.","Le déclin laisse place à une nouvelle croissance.","La destruction d'un écosystème peut parfois permettre l'apparition d'un autre.","Pour cette raison, les fidèles de Quaara ne considèrent pas toujours la destruction comme un mal.","Ils cherchent plutôt à comprendre ce qu'elle provoque.","Cette philosophie peut être difficile à accepter pour les peuples qui cherchent à contrôler leur environnement."]},{title:"Les peuples de Quaara",title_border:"#6f9fd8",type:"text",content:["Les Lythari et les Virelith entretiennent depuis longtemps une relation particulière avec Quaara.","Ils ne la considèrent pas comme une reine de la Nature.","Elle n'est pas leur souveraine.","Elle est une manifestation consciente d'une Force dont ils font eux-mêmes partie.","Leurs traditions cherchent donc moins à dominer leur environnement qu'à apprendre à y vivre.","Cela ne signifie pas qu'ils refusent toute violence.","Lorsqu'une menace pénètre sur leurs terres, ils savent se défendre.","Ils ont simplement appris à faire de leur environnement une partie de leur défense.","Les forêts et les montagnes deviennent ainsi des alliées aussi importantes que les guerriers qui y vivent."]},{title:"Le culte de Quaara",title_border:"#e8553d",type:"text",content:["Les cultes de Quaara possèdent rarement de grands temples.","Les lieux sacrés sont plus souvent :"]},{title:"",type:"list",content:["Des bosquets","Des sources","Des montagnes","Des arbres anciens","Des grottes","Des clairières","Des lieux où plusieurs écosystèmes se rencontrent"]},{title:"",type:"text",content:["Ses prêtres peuvent être guérisseurs, chasseurs, gardiens de territoires, herboristes ou guides.","Certains vivent presque entièrement au contact de la nature.","D'autres vivent au cœur des villes et considèrent que leur rôle consiste justement à rappeler aux citadins qu'ils ne sont pas séparés du monde naturel."]},{title:"Quaara et les autres dieux",title_border:"#c2660a",type:"text",content:["Quaara partage une relation évidente avec Metona.","La Vie donne naissance aux êtres.","La Nature leur offre un monde dans lequel évoluer.","Avec Gusius, elle partage également un lien étroit.","L'Instinct permet aux créatures de survivre.","La Nature leur fournit l'environnement dans lequel cet instinct s'exprime.","Sa relation avec Théomis est plus complexe.","L'Ordre cherche à structurer.","La Nature évolue constamment.","Ils ne sont pas nécessairement ennemis, mais leurs principes peuvent entrer en opposition.","Une civilisation peut chercher à imposer une structure à un territoire que la Nature cherche continuellement à transformer."]},{title:"Symboles",title_border:"#6f9fd8",type:"text",content:"Quaara est généralement représentée par :"},{title:"",type:"list",content:["Une branche","Une feuille","Une racine","Une spirale végétale","Une montagne","Un arbre dont les racines entourent le monde"]},{title:"",type:"text",content:["Certaines représentations montrent un arbre dont une moitié est en fleurs tandis que l'autre se décompose.","Cette image rappelle que croissance et déclin appartiennent au même cycle."]},{title:"Aujourd'hui",title_border:"#e8553d",type:"text",content:["Le culte de Quaara demeure particulièrement important dans les régions sauvages et auprès des peuples vivant en étroite relation avec leur environnement.","Mais son influence dépasse largement ces territoires.","Les agriculteurs, chasseurs, guérisseurs et voyageurs peuvent également lui adresser leurs prières.","Ses fidèles ne demandent pas toujours à la Nature de les protéger.","Ils demandent parfois simplement de comprendre leur place en son sein.","Car pour Quaara, la question n'est pas :","Mais plutôt :"]},{title:"",type:"banner",content:"« Combien de temps pouvons-nous oublier que nous en faisons partie ? »",subtitle:"Citation"}],i=["Les Dieux","Les Forces","Les Forces du Monde","Metona","Gusius","Théomis","Trésabia","Les Lythari","Virelith","La Nature"],u={tags:e,citation:t,surname:n,presentation:r,infos:s,sections:a,related:i};export{t as citation,u as default,s as infos,r as presentation,i as related,a as sections,n as surname,e as tags};
